#include <stdio.h>

static int next_ticket(void) {
    static int ticket = 100;
    ++ticket;
    return ticket;
}

int main(void) {
    int first = next_ticket();
    int second = next_ticket();
    printf("%d %d\n", first, second);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int local_value = 7;
    int *allocated_value = malloc(sizeof *allocated_value);
    if (allocated_value == NULL) {
        fputs("allocation failed\n", stderr);
        return 1;
    }

    *allocated_value = 35;
    printf("local=%d allocated=%d total=%d\n",
           local_value, *allocated_value, local_value + *allocated_value);

    free(allocated_value);
    allocated_value = NULL;
    return 0;
}
